31	        expression = "java(org.springframework.samples.petclinic.util.CustomerCodes.regionOf(owner.getCustomerCode()))")
32	    @Mapping(target = "timezone",
33	        expression = "java(org.springframework.samples.petclinic.util.Localities.timezoneFor(org.springframework.samples.petclinic.util.CustomerCodes.regionOf(owner.getCustomerCode())))")
34	    @Mapping(target = "contactPreference",
35	        expression = "java(owner.getEmail() != null ? \"EMAIL\" : \"PHONE\")")
36	    @Mapping(target = "identityKey", expression = "java(identityKey(owner))")
37	    @Mapping(target = "checkDigit",
38	        expression = "java(org.springframework.samples.petclinic.util.CheckDigits.luhn(owner.getCustomerCode()))")
39	    @Mapping(target = "ageBand", expression = "java(ageBand(owner))")
40	    @Mapping(target = "possibleDuplicate", expression = "java(owner.getPossibleDuplicateOf() != null)")
41	    @Mapping(target = "telephoneDisplay",
42	        expression = "java(org.springframework.samples.petclinic.util.TelephoneFormatter.toDisplay(owner.getTelephone()))")
43	    OwnerDto toOwnerDto(Owner owner);
44	
45	    /** Age band derived from birthDate against registrationDate: MINOR (under 18), ADULT (18-64) or SENIOR (65+); null when birthDate is absent. */
46	    default String ageBand(Owner owner) {
47	        java.time.LocalDate birthDate = owner.getBirthDate();
48	        if (birthDate == null || owner.getRegistrationDate() == null) {
49	            return null;
50	        }
51	        int age = java.time.Period.between(birthDate, owner.getRegistrationDate()).getYears();
52	        if (age < 18) {
53	            return "MINOR";
54	        }
55	        return age < 65 ? "ADULT" : "SENIOR";
56	    }
57	
58	    /** The single duplicate-detection key: normalizedTelephone + '|' + (email or empty) + '|' + (householdId or empty). */
59	    default String identityKey(Owner owner) {
60	        return orEmpty(owner.getTelephone()) + '|' + orEmpty(owner.getEmail()) + '|' + orEmpty(owner.getHouseholdId());
61	    }
62	
63	    default String orEmpty(String value) {
64	        return value == null ? "" : value;
65	    }
66	
67	    /** Membership points: +2 for an email, +1 when namesakeCount is 0, +2 for a household of 3 or more, +3 for tenure over 365 days. */
68	    default int membershipPoints(Owner owner) {
69	        int points = 0;
70	        if (owner.getEmail() != null) {
71	            points += 2;
72	        }
73	        if (Integer.valueOf(0).equals(owner.getNamesakeCount())) {
74	            points += 1;
75	        }
76	        if (owner.getHouseholdMemberCount() != null && owner.getHouseholdMemberCount() >= 3) {
77	            points += 2;
78	        }
79	        if (tenureDays(owner) > 365) {
80	            points += 3;
81	        }
82	        return points;
83	    }
84	
85	    /** Numeric level derived from membershipPoints: 1 (0-1), 2 (2-3), 3 (4-5), 4 (6 or more). */
86	    default Integer membershipLevel(Owner owner) {
87	        int points = membershipPoints(owner);
88	        if (points <= 1) {
89	            return 1;
90	        }
91	        if (points <= 3) {
92	            return 2;
93	        }
94	        return points <= 5 ? 3 : 4;
95	    }
96	
97	    /** Days of tenure since registrationDate; 0 when the date is absent (a new owner has zero tenure). */
98	    default long tenureDays(Owner owner) {
99	        java.time.LocalDate registrationDate = owner.getRegistrationDate();
100	        if (registrationDate == null) {
101	            return 0;
102	        }
103	        return java.time.temporal.ChronoUnit.DAYS.between(registrationDate, java.time.LocalDate.now());
104	    }
105	
106	    /** Derive the '<customerCode>-M<YY>' membership number, where YY is the last two digits of the registrationDate year. */
107	    default String membershipNumber(Owner owner) {
108	        if (owner.getCustomerCode() == null || owner.getRegistrationDate() == null) {
109	            return null;
110	        }
111	        return String.format("%s-M%02d", owner.getCustomerCode(), owner.getRegistrationDate().getYear() % 100);
112	    }
113	
114	    Owner toOwner(OwnerDto ownerDto);
115	
116	    @Mapping(target = "id", ignore = true)
117	    @Mapping(target = "pets", ignore = true)
118	    @Mapping(target = "telephone", source = "telephone", qualifiedByName = "normalizeTelephone")
119	    @Mapping(target = "registrationDate", expression = "java(effectiveRegistrationDate(ownerDto))")
120	    @Mapping(target = "address", expression = "java(org.springframework.samples.petclinic.util.AddressNormalizer.compose(ownerDto.getAddressLine1(), ownerDto.getAddressLine2(), ownerDto.getAddress()))")
121	    Owner toOwner(OwnerFieldsDto ownerDto);
122	
123	    /** The supplied registration date, or today's date when absent, rolled forward off weekends to a business day. */
124	    default java.time.LocalDate effectiveRegistrationDate(OwnerFieldsDto ownerDto) {
125	        java.time.LocalDate supplied = ownerDto.getRegistrationDate();
126	        return org.springframework.samples.petclinic.util.BusinessDays.toBusinessDay(
127	            supplied != null ? supplied : java.time.LocalDate.now());
128	    }
129	
130	    /** Normalize to E.164 so the create path stores, and duplicate detection compares, that form. */
131	    @Named("normalizeTelephone")
132	    default String normalizeTelephone(String telephone) {
133	        return TelephoneNormalizer.toE164(telephone);
134	    }
135	
136	    List<OwnerDto> toOwnerDtoCollection(Collection<Owner> ownerCollection);
137	
138	    Collection<Owner> toOwners(Collection<OwnerDto> ownerDtos);
139	
140	    default OwnerPageDto toOwnerPageDto(@NonNull Page<Owner> ownerPage) {
141	        OwnerPageDto ownerPageDto = new OwnerPageDto();
142	        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
143	        ownerPageDto.setPage(ownerPage.getNumber());
144	        ownerPageDto.setSize(ownerPage.getSize());
145	        ownerPageDto.setTotalElements(ownerPage.getTotalElements());
146	        ownerPageDto.setTotalPages(ownerPage.getTotalPages());
147	        return ownerPageDto;
148	    }
149	}
